-- Unicode normalization (NFC) in pure Lua, since Neovim has no normalization
-- function of its own. Implements the algorithm of Unicode Standard Annex #15
-- with the data in lua/libraries/_unicode_data.lua (generated by
-- scripts/generate-unicode-data.py). Conformance is tested against Unicode's
-- NormalizationTest.txt by scripts/test-unicode-nfc.lua.
--
-- All functions take and return UTF-8 strings. Invalid UTF-8 is never changed:
-- functions that would have to interpret it return nil instead.

local M = {}

-- Hangul syllables are composed and decomposed algorithmically
local S_BASE, L_BASE, V_BASE, T_BASE = 0xAC00, 0x1100, 0x1161, 0x11A7
local L_COUNT, V_COUNT, T_COUNT = 19, 21, 28
local N_COUNT = V_COUNT * T_COUNT
local S_COUNT = L_COUNT * N_COUNT

-- Lookup tables, built from the data module on first use
local decomposition  -- cp → full canonical decomposition (list of cp)
local composition    -- first cp → (second cp → primary composite)
local ccc            -- cp → nonzero canonical combining class
local quick_check    -- cp → "N" or "M" (NFC_QC; absent means "Y")
local marks          -- cp → true for general category M

local function init()
  if decomposition then
    return
  end
  local data = require('libraries._unicode_data')
  M.version = data.version

  local function expand(range_list, value_index)
    local result = {}
    for _, range in ipairs(range_list) do
      local value = value_index and range[value_index] or true
      for cp = range[1], range[2] do
        result[cp] = value
      end
    end
    return result
  end
  ccc = expand(data.combining_class, 3)
  quick_check = expand(data.nfc_quick_check, 3)
  marks = expand(data.marks)

  local function full(cp, out)
    local d = data.decomposition[cp]
    if d then
      for _, c in ipairs(d) do
        full(c, out)
      end
    else
      out[#out + 1] = cp
    end
    return out
  end
  decomposition = {}
  for cp in pairs(data.decomposition) do
    decomposition[cp] = full(cp, {})
  end

  local excluded = {}
  for _, cp in ipairs(data.composition_exclusions) do
    excluded[cp] = true
  end
  composition = {}
  for cp, d in pairs(data.decomposition) do
    if #d == 2 and not excluded[cp] then
      composition[d[1]] = composition[d[1]] or {}
      composition[d[1]][d[2]] = cp
    end
  end
end

-- Decode a UTF-8 string into a list of code points and a list of their byte
-- offsets (1-based). Return nil for invalid UTF-8 (including overlong forms,
-- surrogates, and code points above U+10FFFF).
function M.decode(s)
  local cps, offsets = {}, {}
  local i, n = 1, #s
  while i <= n do
    local b = s:byte(i)
    local cp, len, min
    if b < 0x80 then
      cp, len, min = b, 1, 0
    elseif b >= 0xC2 and b < 0xE0 then
      cp, len, min = b - 0xC0, 2, 0x80
    elseif b >= 0xE0 and b < 0xF0 then
      cp, len, min = b - 0xE0, 3, 0x800
    elseif b >= 0xF0 and b < 0xF5 then
      cp, len, min = b - 0xF0, 4, 0x10000
    else
      return nil
    end
    if i + len - 1 > n then
      return nil
    end
    for j = i + 1, i + len - 1 do
      local c = s:byte(j)
      if c < 0x80 or c >= 0xC0 then
        return nil
      end
      cp = cp * 64 + (c - 0x80)
    end
    if cp < min or cp > 0x10FFFF or (cp >= 0xD800 and cp <= 0xDFFF) then
      return nil
    end
    cps[#cps + 1] = cp
    offsets[#offsets + 1] = i
    i = i + len
  end
  return cps, offsets
end

-- Encode a list of code points as a UTF-8 string
function M.encode(cps)
  local bytes = {}
  for _, cp in ipairs(cps) do
    if cp < 0x80 then
      bytes[#bytes + 1] = string.char(cp)
    elseif cp < 0x800 then
      bytes[#bytes + 1] = string.char(0xC0 + math.floor(cp / 0x40), 0x80 + cp % 0x40)
    elseif cp < 0x10000 then
      bytes[#bytes + 1] = string.char(
        0xE0 + math.floor(cp / 0x1000), 0x80 + math.floor(cp / 0x40) % 0x40, 0x80 + cp % 0x40)
    else
      bytes[#bytes + 1] = string.char(
        0xF0 + math.floor(cp / 0x40000), 0x80 + math.floor(cp / 0x1000) % 0x40,
        0x80 + math.floor(cp / 0x40) % 0x40, 0x80 + cp % 0x40)
    end
  end
  return table.concat(bytes)
end

-- Quick check (UAX #15, section 9): true if `cps` is certainly in NFC, false
-- if it may not be
local function quick_check_yes(cps)
  local last_class = 0
  for _, cp in ipairs(cps) do
    if cp >= 0x300 then
      local class = ccc[cp] or 0
      if class ~= 0 and last_class > class then
        return false
      end
      if quick_check[cp] then
        return false
      end
      last_class = class
    else
      last_class = 0
    end
  end
  return true
end

local function compose_pair(a, b)
  -- Hangul L + V → LV, and LV + T → LVT
  if a >= L_BASE and a < L_BASE + L_COUNT and b >= V_BASE and b < V_BASE + V_COUNT then
    return S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT
  end
  if a >= S_BASE and a < S_BASE + S_COUNT and (a - S_BASE) % T_COUNT == 0
      and b > T_BASE and b < T_BASE + T_COUNT then
    return a + (b - T_BASE)
  end
  local second = composition[a]
  return second and second[b]
end

-- Normalize a list of code points to NFC
local function nfc_cps(cps)
  -- Canonical decomposition
  local d = {}
  for _, cp in ipairs(cps) do
    if cp >= S_BASE and cp < S_BASE + S_COUNT then
      local s = cp - S_BASE
      d[#d + 1] = L_BASE + math.floor(s / N_COUNT)
      d[#d + 1] = V_BASE + math.floor((s % N_COUNT) / T_COUNT)
      if s % T_COUNT ~= 0 then
        d[#d + 1] = T_BASE + s % T_COUNT
      end
    elseif decomposition[cp] then
      for _, c in ipairs(decomposition[cp]) do
        d[#d + 1] = c
      end
    else
      d[#d + 1] = cp
    end
  end
  -- Canonical ordering: stable sort of each run of nonzero combining classes
  for i = 2, #d do
    local class = ccc[d[i]] or 0
    if class ~= 0 then
      local cp, j = d[i], i - 1
      while j >= 1 and (ccc[d[j]] or 0) > class do
        d[j + 1] = d[j]
        j = j - 1
      end
      d[j + 1] = cp
    end
  end
  -- Canonical composition
  local result = {}
  local starter     -- index in `result` of the last starter
  local last_class  -- combining class of the last character in `result`
  for _, cp in ipairs(d) do
    local class = ccc[cp] or 0
    local composite
    if starter then
      local adjacent = (#result == starter)
      if adjacent or (last_class ~= 0 and last_class < class) then
        composite = compose_pair(result[starter], cp)
      end
    end
    if composite then
      result[starter] = composite
    else
      result[#result + 1] = cp
      if class == 0 then
        starter = #result
      end
      last_class = class
    end
  end
  return result
end

-- Return `s` in NFC, or nil if `s` is not valid UTF-8
function M.nfc(s)
  if not s:find('[\128-\255]') then
    return s
  end
  init()
  local cps = M.decode(s)
  if not cps then
    return nil
  end
  if quick_check_yes(cps) then
    return s
  end
  return M.encode(nfc_cps(cps))
end

-- Return true if `s` is in NFC, false if not, and nil if `s` is not valid UTF-8
function M.is_nfc(s)
  local normalized = M.nfc(s)
  if normalized == nil then
    return nil
  end
  return normalized == s
end

-- Look-alikes that Julia also folds in identifiers, beyond NFC
local folds = {
  ['\u{00B5}'] = '\u{03BC}', -- µ MICRO SIGN → μ GREEK SMALL LETTER MU
  ['\u{210F}'] = '\u{0127}', -- ℏ PLANCK CONSTANT OVER TWO PI → ħ
  ['\u{025B}'] = '\u{03B5}', -- ɛ LATIN SMALL LETTER OPEN E → ε
}

-- Return the key under which equivalent forms of a character are grouped: its
-- NFC form, with the look-alikes folded that Julia also folds in identifiers
function M.key(form)
  local key = M.nfc(form) or form
  for from, to in pairs(folds) do
    key = key:gsub(from, to)  -- the UTF-8 bytes contain no pattern characters
  end
  return key
end

-- Return the "forms" in `s` that can have equivalent spellings: each non-ASCII
-- character, and each ASCII character followed by combining marks, together
-- with the combining marks that follow it. Return a list of { form, col }
-- with the 1-based byte column, or nil if `s` is not valid UTF-8.
function M.forms(s)
  if not s:find('[\128-\255]') then
    return {}
  end
  init()
  local cps, offsets = M.decode(s)
  if not cps then
    return nil
  end
  local result = {}
  local i = 1
  while i <= #cps do
    local j = i
    while j < #cps and marks[cps[j + 1]] do
      j = j + 1
    end
    if cps[i] >= 0x80 or j > i then
      local last = (j < #cps) and offsets[j + 1] - 1 or #s
      result[#result + 1] = { s:sub(offsets[i], last), offsets[i] }
    end
    i = j + 1
  end
  return result
end

-- Return true if the character that starts at byte `i` of `s` is a combining
-- mark (general category M)
function M.mark_at(s, i)
  local b = s:byte(i)
  if not b or b < 0x80 then
    return false
  end
  init()
  local len = (b >= 0xF0 and 4) or (b >= 0xE0 and 3) or 2
  local cps = M.decode(s:sub(i, i + len - 1))
  return cps ~= nil and marks[cps[1]] == true
end

-- Return the code points of `s` as a string like "U+0048 U+0302"
function M.codepoints(s)
  local cps = M.decode(s) or {}
  local parts = {}
  for _, cp in ipairs(cps) do
    parts[#parts + 1] = ('U+%04X'):format(cp)
  end
  return table.concat(parts, ' ')
end

return M

